package com.bank.spark.service;

import com.bank.spark.model.RowGroup;

import java.math.BigDecimal;
import java.util.List;

// Simulates how each source applies a "amount > threshold" filter.
public class PushdownReader {

    // Parquet: skip row groups whose max is below the threshold using stats.
    public int parquetRowsRead(List<RowGroup> groups, BigDecimal threshold) {
        int read = 0;
        for (RowGroup g : groups) {
            if (g.getMaxAmount().compareTo(threshold) > 0) {
                read += g.getRowCount();   // this group MIGHT contain matches → read it
            }
            // else: entire group skipped by min/max pushdown
        }
        return read;
    }

    // CSV: no statistics → must read every row regardless of the filter.
    public int csvRowsRead(List<RowGroup> groups) {
        return groups.stream().mapToInt(RowGroup::getRowCount).sum();
    }

    // JDBC: predicate becomes SQL WHERE → DB returns only matches (simulate match ratio).
    public int jdbcRowsReturned(int totalRows, double matchRatio) {
        return (int) Math.round(totalRows * matchRatio);
    }
}
