package com.bank.spark;

import com.bank.spark.model.RowGroup;
import com.bank.spark.service.PushdownReader;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PredicatePushdownDemo {

    private static final Logger log = Logger.getLogger(PredicatePushdownDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PushdownReader reader = new PushdownReader();
        BigDecimal threshold = new BigDecimal("50000");

        // Four Parquet row groups with different amount ranges.
        List<RowGroup> groups = List.of(
                new RowGroup(0, new BigDecimal("100"),   new BigDecimal("9000"),   250_000),
                new RowGroup(1, new BigDecimal("10000"), new BigDecimal("48000"),  250_000),
                new RowGroup(2, new BigDecimal("40000"), new BigDecimal("120000"), 250_000),
                new RowGroup(3, new BigDecimal("55000"), new BigDecimal("900000"), 250_000)
        );
        int total = groups.stream().mapToInt(RowGroup::getRowCount).sum();

        int parquetRead = reader.parquetRowsRead(groups, threshold);
        log.info(() -> "Parquet (amount > 50000): read " + parquetRead + " of " + total
                + " rows — row groups 0 and 1 skipped by min/max pushdown");

        int csvRead = reader.csvRowsRead(groups);
        log.warning(() -> "CSV (amount > 50000): read ALL " + csvRead
                + " rows — no statistics, every row parsed before filtering");

        int jdbcRows = reader.jdbcRowsReturned(total, 0.30);
        log.info(() -> "JDBC (amount > 50000): DB executed WHERE, returned only " + jdbcRows
                + " matching rows using its index");

        log.info("Pushdown is powerful with Parquet/JDBC and weak with CSV — store analytics data columnar.");
    }
}

